    random.seed(seed)

    def generate_cnf(n):
        cnf = []
        for _ in range(n * 3):
            clause = [random.randint(1, n), -random.randint(1, n)]
            if random.choice([True, False]):
                clause[0] *= -1
            if random.choice([True, False]):
                clause[1] *= -1
            cnf.append(clause)
        return cnf

    def backtrack():
        assignment = [None] * (n + 1)
        stack = []

        def search(t):
            if t > n:
                return True
            for val in [-1, 1]:
                assignment[t] = val
                if is_satisfiable(cnf):
                    stack.append((t, val))
                    if search(t + 1):
                        return True
                    stack.pop()
            assignment[t] = None
            return False

        return search(1)

    def is_satisfiable(cnf):
        while stack:
            t, val = stack.pop()
            assignment[t] = val
            for clause in cnf:
                if not any([assignment[abs(lit)] == (lit > 0) for lit in clause]):
                    break
            else:
                return True
        return False

    def read_twice_bp_size(cnf):
        n = len(cnf)
        dp = [[False] * (n + 1) for _ in range(n + 1)]

        def backtrack(i, j):
            if i > n or j > n:
                return 0
            if dp[i][j]:
                return 0
            dp[i][j] = True
            size = 1
            for clause in cnf:
                if not any([assignment[abs(lit)] == (lit > 0) for lit in clause]):
                    break
            else:
                size += backtrack(i + 1, j)
            return size

        return backtrack(1, 1)

